import 'package:flutter/cupertino.dart';
import '../../core/business_api_client.dart';

final class WalletPage extends StatefulWidget { const WalletPage({super.key, this.api}); final BusinessApiClient? api; @override State<WalletPage> createState()=>_WalletPageState(); }
final class _WalletPageState extends State<WalletPage> { final amount=TextEditingController(); final address=TextEditingController(); String? status; @override void dispose(){amount.dispose();address.dispose();super.dispose();} Future<void> withdraw() async { try { final r=await widget.api?.requestWithdrawal(amount:amount.text.trim(),address:address.text.trim(),clientOrderId:'mobile-${DateTime.now().millisecondsSinceEpoch}',reasonCode:'USER_WITHDRAWAL'); setState(()=>status='提现申请已提交：${r?['status']??'审核中'}'); } catch(e){setState(()=>status=e.toString());} } @override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(20),children:[const Text('USDT 钱包',style:TextStyle(fontSize:32,fontWeight:FontWeight.w700)),const SizedBox(height:18),CupertinoListSection.insetGrouped(children:[CupertinoListTile(leading:const Icon(CupertinoIcons.creditcard_fill,color:CupertinoColors.systemGreen),title:const Text('USDT-TRC20'),subtitle:FutureBuilder<Map<String,dynamic>>(future:widget.api?.walletBalance(),builder:(_,s)=>Text(s.hasError?'钱包暂不可用':'${s.data?['balance']??'加载中…'} USDT')),trailing:const Text('6位小数'))]),CupertinoListSection.insetGrouped(header:const Text('充值'),children:[CupertinoListTile(leading:const Icon(CupertinoIcons.arrow_down_circle),title:const Text('获取充值地址'),onTap:()async{try{final r=await widget.api?.walletDepositAddress();if(mounted)showCupertinoDialog(context:context,builder:(_)=>CupertinoAlertDialog(title:const Text('TRC20 充值地址'),content:Text(r?['address']?.toString()??'暂未生成'),actions:[CupertinoDialogAction(child:const Text('关闭'),onPressed:()=>Navigator.pop(context))]));}catch(e){setState(()=>status=e.toString());}})]),CupertinoListSection.insetGrouped(header:const Text('提现'),children:[CupertinoTextField(controller:amount,placeholder:'提现金额（6位小数）',keyboardType:TextInputType.number,padding:const EdgeInsets.all(14)),CupertinoTextField(controller:address,placeholder:'USDT-TRC20 地址',padding:const EdgeInsets.all(14)),CupertinoButton.filled(onPressed:widget.api==null?null:withdraw,child:const Text('提交提现申请'))]),if(status!=null)Text(status!),const Text('提现状态：申请 → 审核 → 托管方处理 → 链上确认',style:TextStyle(color:CupertinoColors.secondaryLabel))]); }
